      project(pt.x, pt.y, pt.z, tmp);
      var da = 0.12 + (1 - (tmp[2] + 2) / 4) * 0.35;
      g.fillStyle = 'rgba(' + T.dust + ',' + Math.max(0.05, da * (T.light ? 0.7 : 1)).toFixed(3) + ')';
